"""Pure state engine: decides the next service state from one check result.

No I/O here, so it is fully table-testable (PLAN.md section 10). All thresholds
come from Settings; the rules are DECISIONS.md D5-D8 plus the O-1/O-2 answers:

- 2xx within the slow threshold -> HEALTHY
- 2xx over the slow threshold   -> DEGRADED (slow but alive)
- 1st failure                   -> DEGRADED, no incident
- N consecutive failures        -> DOWN (incident opens)
- success while DOWN            -> recovering; after N consecutive successes the
  incident resolves, to HEALTHY (fast) or DEGRADED (if the latest check was slow)
- any failure resets the success counter, any success resets the failure counter
"""
from dataclasses import dataclass

# Events the caller must act on. The engine only decides; incidents.py acts.
OPEN, APPEND_FAILURE, RECOVERING, RESOLVE = "open", "append_failure", "recovering", "resolve"


@dataclass(frozen=True)
class Check:
    """Outcome of one health check."""
    ok: bool
    slow: bool = False


@dataclass(frozen=True)
class Counters:
    failures: int = 0
    successes: int = 0


@dataclass(frozen=True)
class Transition:
    state: str                       # unknown | healthy | degraded | down
    counters: Counters
    events: tuple = ()


def next_state(
    current: str,
    counters: Counters,
    check: Check,
    failures_to_down: int = 2,
    successes_to_recover: int = 2,
) -> Transition:
    f, s = counters.failures, counters.successes

    if check.ok:                                   # 2xx (fast or slow)
        f2, s2 = 0, s + 1
        if current == "down":
            if s2 >= successes_to_recover:         # O-1: slow success still resolves
                state = "degraded" if check.slow else "healthy"
                return Transition(state, Counters(0, s2), (RESOLVE,))
            return Transition("degraded", Counters(0, s2), (RECOVERING,))   # O-2
        state = "degraded" if check.slow else "healthy"
        return Transition(state, Counters(0, s2), ())

    f2, s2 = f + 1, 0                              # failure: non-2xx, timeout or error
    if current == "down":
        return Transition("down", Counters(f2, 0), (APPEND_FAILURE,))
    if f2 >= failures_to_down:
        return Transition("down", Counters(f2, 0), (OPEN,))
    return Transition("degraded", Counters(f2, 0), ())

"""Runs one HTTP health check against a service. Async and self-contained, so a
slow or dead service can never delay checks of other services (must-have 2).
"""
import time
from dataclasses import dataclass

import httpx


@dataclass(frozen=True)
class CheckResult:
    ok: bool                  # 2xx within the request timeout
    slow: bool                # 2xx but over the slow threshold (still a success)
    status_code: int | None
    latency_ms: int | None
    error: str | None         # INTERNAL ONLY: never rendered on the public page


async def run_check(
    client: httpx.AsyncClient,
    health_url: str,
    timeout_ms: int,
    slow_threshold_ms: int,
) -> CheckResult:
    """GET the health URL once. Any non-2xx, timeout or connection error is a failure."""
    t0 = time.perf_counter()
    try:
        r = await client.get(health_url, timeout=timeout_ms / 1000)
    except httpx.TimeoutException:
        latency = int((time.perf_counter() - t0) * 1000)
        return CheckResult(False, False, None, latency, f"timeout after {timeout_ms} ms")
    except httpx.RequestError as e:
        latency = int((time.perf_counter() - t0) * 1000)
        return CheckResult(False, False, None, latency, f"connection error: {type(e).__name__}")

    latency = int((time.perf_counter() - t0) * 1000)
    if 200 <= r.status_code < 300:
        return CheckResult(True, latency > slow_threshold_ms, r.status_code, latency, None)
    return CheckResult(False, False, r.status_code, latency, f"HTTP {r.status_code}")

